// Typed wrappers — one per RPC in plan/02 (S600 + S605).
// Each wrapper is a thin pass-through over the user-JWT (or service-role, for
// worker RPCs) Supabase client, so RLS + the DB permission checks apply.
// Argument names are the SQL p_* names exactly; return types come from
// database.types.ts (generated by `pnpm gen:types`).
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from './database.types';

type FnName = keyof Database['public']['Functions'];
type Args<Fn extends FnName> = Database['public']['Functions'][Fn]['Args'];

/** Every RPC in plan/02 §RPC catalog. The unit test asserts this list has a wrapper. */
export const RPC_NAMES = [
  'ds_create_design_version',
  'ds_create_tech_pack',
  'ds_transition_tech_pack',
  'ds_tech_pack_snapshot',
  'ds_create_rfq',
  'ds_invite_vendor_to_rfq',
  'ds_publish_rfq',
  'ds_close_rfq',
  'ds_close_due_rfqs',
  'ds_answer_question',
  'ds_award_rfq',
  'ds_invite_supplier_user',
  'ds_revoke_supplier',
  'ds_enqueue_job',
  'ds_rfq_unsealed',
  'ds_my_vendor_ids',
  'supplier_accept_invite',
  'supplier_get_nda',
  'supplier_accept_nda',
  'supplier_my_rfqs',
  'supplier_get_rfq',
  'supplier_authorize_asset_view',
  'supplier_save_bid',
  'supplier_submit_bid',
  'supplier_withdraw_bid',
  'supplier_ask_question',
  'supplier_decline_rfq',
  'supplier_register_upload',
  'supplier_authorize_release',
  'ds_claim_jobs',
  'ds_heartbeat_job',
  'ds_finish_job',
  'ds_reap_stale_jobs',
  'ds_claim_browser_jobs',
  'ds_heartbeat_browser_job',
  'ds_finish_browser_job',
] as const satisfies readonly FnName[];
export type RpcName = (typeof RPC_NAMES)[number];

// --- Staff: designs & tech packs -------------------------------------------
export function dsCreateDesignVersion(
  client: SupabaseClient<Database>,
  args: Args<'ds_create_design_version'>,
) {
  return client.rpc('ds_create_design_version', args);
}

